visual.anim:
const o = ease(span(t, 0.3, 2.0));
const i = ease(span(t, 1.2, 2.6));
const r1 = $('r1'), r2 = $('r2');
const s1 = sc(290 + o * 350);
r1.style.opacity = o; r1.style.width = s1 + 'px'; r1.style.height = s1 + 'px';
const s2 = sc(110 + i * 90);
r2.style.opacity = i; r2.style.width = s2 + 'px'; r2.style.height = s2 + 'px';

const ws = el.querySelectorAll('.cw'), ret = el.querySelector('.reticle');
const prog = clamp(span(t, 0.4, 3.0), 0, 1) * (ws.length - 1);
ws.forEach(function(w, i){ w.classList.toggle('sharp', Math.abs(i - prog) < 0.5); });
const cur = Math.min(Math.max(prog, 0.001), ws.length - 1.001);
const li = Math.floor(cur);
const a = ws[li].getBoundingClientRect();
const b = ws[Math.min(li + 1, ws.length - 1)].getBoundingClientRect();
const hr = el.getBoundingClientRect();
const frac = cur - li;
const x = (a.left - hr.left) + ((b.left - a.left) * frac) - sc(12);
ret.style.transform = 'translate(' + x + 'px,' + (a.top - hr.top - sc(10)) + 'px)';
ret.style.width = (a.width + sc(24)) + 'px';
ret.style.height = (a.height + sc(20)) + 'px';
ret.style.opacity = 1;

const blocks = el.querySelectorAll('.blk');
const filled = ease(span(t, 0.3, 1.8)) * blocks.length;
blocks.forEach(function(b, i){
  const on = i < filled;
  b.style.opacity = on ? 1 : 0;
  b.style.background = '#00d4ff';
  if (on) { const age = filled - i; b.style.opacity = age < 3 ? 0.45 : 1; }
});
const drop = ease(span(t, 2.0, 2.7));
if (drop > 0) {
  const keepFrom = Math.floor(blocks.length * 0.75);
  blocks.forEach(function(b, i){
    if (i < keepFrom) { b.style.opacity = 1 - drop * 0.85; b.style.background = '#7a2341'; }
  });
}
$('bd').style.opacity = ease(span(t, 2.4, 2.9));
